describeConvex("collaboration invitation delivery", () => {
  test("lists email-addressed invitations after the invitee signs in", async () => {
    const { t } = setup();
    const lixId = "pending-lix";
    await t.run(async (ctx) => {
      const storageId = await ctx.storage.store(new Blob(["shared draft"]));
      await ctx.db.insert("sharedLixBlobs", {
        lixId,
        ownerId,
        folioId: "folio-1",
        folioName: "A shared draft",
        storageId,
        createdAt: 1,
        updatedAt: 1,
      });
      await ctx.db.insert("collaborators", {
        lixId,
        userId: "invitee@example.com",
        role: "commenter",
        status: "pending",
        invitedBy: ownerId,
        invitedAt: 2,
      });
    });
    const invitee = t.withIdentity({
      tokenIdentifier: "test-issuer|invitee",
      email: "Invitee@Example.com",
    });

    expect(
      await invitee.query(api.collaboration.listPendingInvitations, {}),
    ).toEqual([
      {
        lixId,
        folioName: "A shared draft",
        role: "commenter",
        invitedAt: 2,
      },
    ]);

    expect(
      await invitee.mutation(api.collaboration.acceptInvitation, { lixId }),
    ).toEqual({ role: "commenter" });
    expect(
      await invitee.query(api.collaboration.listPendingInvitations, {}),
    ).toEqual([]);
    expect(await invitee.query(api.collaboration.listSharedWithMe, {})).toEqual(
      [
        {
          lixId,
          folioId: "folio-1",
          folioName: "A shared draft",
          role: "commenter",
          createdAt: 1,
          updatedAt: 1,
        },
      ],
    );
  });

  test("local development creates an invitation without claiming email delivery", async () => {
    vi.stubEnv("SITE_URL", "http://localhost:5173");
    vi.stubEnv("RESEND_API_KEY", "");
    const { t, owner } = setup();
    await seedOwner(t, "local-lix");

    const result = await owner.action(api.collaboration.inviteCollaborator, {
      lixId: "local-lix",
      folioName: "Local draft",
      email: "editor@example.com",
      role: "editor",
    });

    expect(result).toEqual({
      alreadyInvited: false,
      role: "editor",
      emailDelivered: false,
    });
    const pending = await t.run((ctx) =>
      ctx.db
        .query("collaborators")
        .withIndex("by_lixId", (q) => q.eq("lixId", "local-lix"))
        .collect(),
    );
    expect(pending).toHaveLength(2);
    expect(pending.find((row) => row.status === "pending")?.userId).toBe(
      "editor@example.com",
    );
  });

  test("production configuration failure rolls the pending invitation back", async () => {
    vi.stubEnv("SITE_URL", "https://twyne.example");
    vi.stubEnv("RESEND_API_KEY", "");
    const { t, owner } = setup();
    await seedOwner(t, "production-lix");

    await expect(
      owner.action(api.collaboration.inviteCollaborator, {
        lixId: "production-lix",
        folioName: "Production draft",
        email: "editor@example.com",
        role: "commenter",
      }),
    ).rejects.toThrow("email delivery is not configured");

    const rows = await t.run((ctx) =>
      ctx.db
        .query("collaborators")
        .withIndex("by_lixId", (q) => q.eq("lixId", "production-lix"))
        .collect(),
    );
    expect(rows).toHaveLength(1);
    expect(rows[0].role).toBe("owner");
  });
});

describeConvex("collaboration sharing and permissions", () => {
  async function seedShare(
    t: ReturnType<typeof convexTest>,
    lixId: string,
    folioId: string,
  ) {
    await t.run(async (ctx) => {
      const storageId = await ctx.storage.store(new Blob(["blob"]));
      await ctx.db.insert("sharedLixBlobs", {
        lixId,
        ownerId,
        folioId,
        folioName: "Draft",
        storageId,
        createdAt: 1,
        updatedAt: 1,
      });
    });
    await seedOwner(t, lixId);
  }

  test("a folio maps to one share and a used lixId cannot gain an owner", async () => {
    const { t } = setup();
    await seedShare(t, "lix-a", "folio-a");
    const storageId = await t.run((ctx) =>
      ctx.storage.store(new Blob(["second"])),
    );

    expect(
      await t.mutation(internal.collaboration.createShareRecord, {
        lixId: "lix-b",
        ownerId,
        folioId: "folio-a",
        folioName: "Draft",
        storageId,
      }),
    ).toEqual({ created: false, lixId: "lix-a" });

    await expect(
      t.mutation(internal.collaboration.createShareRecord, {
        lixId: "lix-a",
        ownerId: "test-issuer|intruder",
        folioId: "folio-x",
        folioName: "Mine now",
        storageId,
      }),
    ).rejects.toThrow("already in use");

    const owners = await t.run((ctx) =>
      ctx.db
        .query("collaborators")
        .withIndex("by_lixId", (q) => q.eq("lixId", "lix-a"))
        .collect(),
    );
    expect(owners.map((row) => row.userId)).toEqual([ownerId]);
  });

  test("only the owner can invite, and a declined invite is reopened", async () => {
    const { t, owner } = setup();
    await seedShare(t, "lix-c", "folio-c");
    const stranger = t.withIdentity({
      tokenIdentifier: "test-issuer|stranger",
      email: "stranger@example.com",
    });

    await expect(
      t.mutation(internal.collaboration.createInvitation, {
        lixId: "lix-c",
        email: "x@example.com",
        role: "editor",
        invitedBy: "test-issuer|stranger",
      }),
    ).rejects.toThrow("Not a collaborator");

    const first = await t.mutation(internal.collaboration.createInvitation, {
      lixId: "lix-c",
      email: "Editor@Example.com",
      role: "editor",
      invitedBy: ownerId,
    });
    expect(first.alreadyInvited).toBe(false);

    const invitee = t.withIdentity({
      tokenIdentifier: "test-issuer|editor",
      email: "editor@example.com",
    });
    await invitee.mutation(api.collaboration.rejectInvitation, {
      lixId: "lix-c",
    });

    const again = await t.mutation(internal.collaboration.createInvitation, {
      lixId: "lix-c",
      email: "editor@example.com",
      role: "commenter",
      invitedBy: ownerId,
    });
    expect(again).toEqual({
      alreadyInvited: false,
      role: "commenter",
      invitationId: first.invitationId,
    });
    expect(
      await invitee.mutation(api.collaboration.acceptInvitation, {
        lixId: "lix-c",
      }),
    ).toEqual({ role: "commenter" });

    expect(
      await stranger.query(api.collaboration.getSharedLixMeta, {
        lixId: "lix-c",
      }),
    ).toBeNull();
    await expect(
      invitee.mutation(api.collaboration.updateRole, {
        lixId: "lix-c",
        userId: "test-issuer|editor",
        role: "editor",
      }),
    ).rejects.toThrow("Requires owner");
    expect(
      await owner.query(api.collaboration.getMyRole, { lixId: "lix-c" }),
    ).toEqual({ role: "owner" });
  });
});

/**
 * Client-side multiplayer helpers.
 *
 * Three flows:
 *
 *   1. Share (owner): open a fresh Lix holding only the active folio's
 *      manuscript → upload it through `shareFolio` → enable sync on it.
 *   2. Join (collaborator): accept any pending invitation → GET the blob via
 *      the LSP `get-v1` endpoint → open it as the shared session.
 *   3. Presence: heartbeat every 3s with cursor + selection; subscribe to
 *      `getPresence` for the live roster.
 *
 * The shared Lix is separate from the writer's local store (see the shared
 * session in lix.ts), so other folios, the bibliography and pending
 * suggestions never leave the device. The SDK's sync loop starts with every
 * open Lix and pushes/pulls through /lsp/* once `lix_sync` is "true" and
 * `lix_server_url` is set.
 */
import type { ConvexClient } from "convex/browser";
import { api } from "../../convex/_generated/api";
import {
  closeSharedLix,
  enableSharedSync,
  installSharedLix,
  openShareableLix,
  sharedLixBlob,
  sharedSessionLixId,
  syncDraftToLix,
} from "./lix";
import { closeLix, openLixInMemory } from "@lix-js/sdk";

/** The SDK appends `/lsp/<route>` itself, so this is the bare site origin. */
function lixServerUrl(): string {
  const baseUrl = (
    (import.meta.env.VITE_CONVEX_SITE_URL as string | undefined) ?? ""
  ).replace(/\/$/, "");
  if (!baseUrl) throw new Error("CONVEX_SITE_URL not configured");
  return baseUrl;
}

const PRESENCE_INTERVAL_MS = 3000;
const PRESENCE_STALE_MS = 30_000;

let _presenceTimer: ReturnType<typeof setInterval> | null = null;
let _currentLixId: string | null = null;
let _presenceOnHide: (() => void) | null = null;

export const DRAFT_SNAPSHOT_REQUEST = "twyne:request-draft-snapshot";

export interface DraftSnapshotRequest {
  folioId: string;
  html?: string;
}

/** Read the canonical HTML directly from the mounted Tiptap editor. */
export function requestActiveDraftSnapshot(folioId: string): string {
  if (typeof window === "undefined") {
    throw new Error("The manuscript editor is not available.");
  }
  const detail: DraftSnapshotRequest = { folioId };
  window.dispatchEvent(
    new CustomEvent<DraftSnapshotRequest>(DRAFT_SNAPSHOT_REQUEST, { detail }),
  );
  if (detail.html === undefined) {
    throw new Error("The manuscript is still opening. Try sharing again.");
  }
  return detail.html;
}

/**
 * Promote a local folio to a shared, server-hosted Lix instance containing
 * only that folio's manuscript. Returns the new document's lixId.
 */
export async function promoteToShared(
  client: ConvexClient,
  folioId: string,
  folioName: string,
  draftHtml: string,
): Promise<{ lixId: string }> {
  const serverUrl = lixServerUrl();
  const draftLixId = await openShareableLix(folioId);
  let result: { lixId: string; alreadyShared: boolean };
  try {
    await syncDraftToLix(folioId, draftHtml);
    const blob = await sharedLixBlob();
    result = await client.action(api.collaboration.shareFolio, {
      folioId,
      folioName,
      lixId: draftLixId,
      blob: await blob.arrayBuffer(),
    });
    if (!result.alreadyShared) await enableSharedSync(serverUrl);
  } catch (error) {
    await closeSharedLix(draftLixId);
    throw error;
  }
  if (result.alreadyShared) {
    // Another tab shared this folio first. Open that document instead of
    // the copy just built, which the server discarded.
    await closeSharedLix(draftLixId);
    await joinSharedLix(client, result.lixId);
    return { lixId: result.lixId };
  }
  _currentLixId = draftLixId;
  return { lixId: draftLixId };
}

/**
 * Open a shared document: fetch its blob from the relay, open it as the
 * shared session for its folio, and start syncing. Owners reopening their
 * own share use this too, so their edits keep flowing after a reload.
 */
export async function joinSharedLix(
  client: ConvexClient,
  lixId: string,
): Promise<{ folioId: string; role: "owner" | "editor" | "commenter" }> {
  const meta = await client.query(api.collaboration.getSharedLixMeta, {
    lixId,
  });
  if (!meta) throw new Error("Not a collaborator on this document.");
  if (sharedSessionLixId() === lixId) {
    return { folioId: meta.folioId, role: meta.role };
  }

  const serverUrl = lixServerUrl();
  const resp = await fetch(`${serverUrl}/lsp/get-v1`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ lix_id: lixId }),
  });
  if (!resp.ok) {
    throw new Error(`Failed to fetch shared Lix (${resp.status})`);
  }

  const lix = await openLixInMemory({
    blob: await resp.blob(),
    providePlugins: [
      (await import("@lix-js/plugin-json")).plugin as unknown as any,
    ],
  });
  try {
    await installSharedLix(lixId, meta.folioId, lix);
  } catch (error) {
    await closeLix({ lix });
    throw error;
  }
  await enableSharedSync(serverUrl);
  _currentLixId = lixId;
  return { folioId: meta.folioId, role: meta.role };
}

/** Leave a shared document; its folio falls back to the local store. */
export async function leaveSharedLix(lixId: string): Promise<void> {
  if (sharedSessionLixId() !== lixId) return;
  await closeSharedLix(lixId);
}

/* ── Remote → local sync ────────────────────────────────────────── */

import type { Editor } from "@tiptap/core";
import { getDraftBlocks, getDraftTypstSource } from "./lix";
