/** Make `lix` the shared document for `folioId`, closing any previous one. */
export async function installSharedLix(
  lixId: string,
  folioId: string,
  lix: LixInstance,
): Promise<void> {
  await closeSharedLix();
  _shared = { lixId, folioId, lix };
  forgetMirror(folioId);
