  window.addEventListener(
    "twyne:user-comments-changed",
    onUserCommentsChanged,
  );
  const onTransaction = ({
    transaction,
  }: {
    transaction: { docChanged: boolean };
  }) => {
    if (transaction.docChanged && editor && !editor.isDestroyed)
      syncCommentMarkResolution(editor, knownComments);
  };
  editor?.on("transaction", onTransaction);
  onUserCommentsChanged();
  cleanup(() => {
    disposed = true;
    editor?.off("transaction", onTransaction);
    window.removeEventListener(
      "twyne:delete-user-comment",
      onDeleteUserComment,
    );
    window.removeEventListener(
      "twyne:toggle-user-comment-resolved",
      onToggleUserCommentResolved,
    );
    window.removeEventListener(
      "twyne:user-comments-changed",
      onUserCommentsChanged,
    );
  });
});

/** Open the writer's note beside the selected passage without filing it. */
const openWriterMarginComposer = $(
  (range: { from: number; to: number }) => {
    const editor = store.editor;
    if (!editor || range.from >= range.to) return;
    const quote = editor.state.doc.textBetween(range.from, range.to, " ");
    if (!quote.trim()) return;

    const start = editor.view.coordsAtPos(range.from);
    const end = editor.view.coordsAtPos(range.to);
    const pageRect = editor.view.dom
      .closest<HTMLElement>(".page-canvas")
      ?.getBoundingClientRect();
    const geom = computeMarginCardGeometry({
      vw: window.innerWidth,
      vh: window.innerHeight,
      rect: {
        left: Math.min(start.left, end.left),
        top: Math.min(start.top, end.top),
        bottom: Math.max(start.bottom, end.bottom),
      },
      page: pageRect
        ? { left: pageRect.left, right: pageRect.right }
        : {
            left: Math.min(start.left, end.left),
            right: Math.max(start.right, end.right),
          },
      idealH: 360,
    });
    const prior = store.userCommentPopover;
    const restoreDraft =
      prior?.mode === "compose" &&
      prior.from === range.from &&
      prior.to === range.to
        ? prior.draft
        : "";
    store.userCommentPopover = {
      mode: "compose",
      visible: true,
      id: "draft-margin",
      author: "You",
      text: "",
      quote,
      createdAt: Date.now(),
      x: geom.x,
      top: geom.top,
      bottom: geom.bottom,
      maxH: geom.maxH,
      from: range.from,
      to: range.to,
      resolved: false,
      replies: [],
      draft: restoreDraft,
    };
    store.selectionAction = null;
  },
);

