{store.activeFolioId &&
  hasAuthenticatedConvexIdentity(auth.value) && (
    <ShareDialog
      folioId={store.activeFolioId}
      folioName={
        store.folios.find((f) => f.id === store.activeFolioId)
          ?.name ?? "Untitled"
      }
      onShared$={$(
        async (lixId: string, draftHtml?: string) => {
          const client = clientSig.value;
          if (!client) return;
          // Open (or reuse) the synced copy before the editor
          // remounts into shared mode, so remote polling never
          // reads this folio from the local store.
          const { joinSharedLix } = await import(
            "../../utils/collaboration"
          );
          try {
            await joinSharedLix(client, lixId);
          } catch (err) {
            reportApplicationDiagnostic(
              "twyne:editor:open-own-share",
              err,
              { operation: "open-own-share" },
            );
            return;
          }
          if (draftHtml !== undefined) {
            store.editorSeed = draftHtml;
          }
          store.sharedLixId = lixId;
          store.sharedRole = "owner";
        },
      )}
      onUnshared$={$(() => {
        // Only the owner's own share is tracked here; a
        // collaborator's joined document is not "unshared"
        // by switching to a folio of theirs.
        if (store.sharedRole === "owner") {
          store.sharedLixId = null;
          store.sharedRole = null;
        }
