351	  const staleKeys = [
352	    ...changed.map((b) => blockKey(folioId, b.id)),
353	    ...removed.map((id) => blockKey(folioId, id)),
354	    ...(orderChanged ? [orderKey(folioId)] : []),
355	    ...(sourceChanged ? [sourceKey(folioId)] : []),
