export async function readFileAsJson<T>(path: string): Promise<T | null> {
  const lix = await getLix();
  const row = await lix.db
    .selectFrom("file")
    .where("path", "=", path)
    .select("data")
    .executeTakeFirst();
  if (!row) return null;
  const parsed = JSON.parse(new TextDecoder().decode(row.data));
  return parsed as T | null;
}

export async function writeFileAsJson(
  path: string,
  data: unknown,
): Promise<void> {
  const lix = await getLix();
  const encoded = new TextEncoder().encode(JSON.stringify(data));
  const existing = await lix.db
    .selectFrom("file")
    .where("path", "=", path)
    .select("id")
    .executeTakeFirst();

  if (existing) {
    await lix.db
      .updateTable("file")
      .set({ data: encoded })
      .where("path", "=", path)
      .execute();
  } else {
    await lix.db.insertInto("file").values({ path, data: encoded }).execute();
  }
  markDirty();
}

/* ── key_value primitives ───────────────────────────────────────── */

async function kvGet(
  lix: LixInstance,
  key: string,
): Promise<string | null> {
  const row = await lix.db
    .selectFrom("key_value")
    .where("key", "=", key)
    .select("value")
    .executeTakeFirst();
  return row?.value ?? null;
}

async function kvUpsert(
  lix: LixInstance,
  key: string,
  value: string,
): Promise<void> {
  const existing = await lix.db
    .selectFrom("key_value")
    .where("key", "=", key)
    .select("key")
    .executeTakeFirst();
  if (existing) {
    await lix.db
      .updateTable("key_value")
      .set({ value })
      .where("key", "=", key)
      .execute();
  } else {
    await lix.db.insertInto("key_value").values({ key, value }).execute();
  }
}

