    ...changed.map((b) => blockKey(folioId, b.id)),
    ...removed.map((id) => blockKey(folioId, id)),
    ...(orderChanged ? [orderKey(folioId)] : []),
    ...(sourceChanged ? [sourceKey(folioId)] : []),
