          .deleteFrom("key_value")
          .where("key", "like", `tw:draft:${folioId}:%`)
          .execute();
        await db
          .insertInto("key_value")
          .values([
            ...blocks.map((block) => ({
              key: blockKey(folioId, block.id),
              value: block.html,
            })),
            {
              key: orderKey(folioId),
              value: JSON.stringify(blocks.map((block) => block.id)),
            },
            ...(draft.typstSource !== undefined
              ? [{ key: sourceKey(folioId), value: draft.typstSource }]
              : []),
          ])
          .execute();
      });
    }
    return lix;
  } catch (error) {
    await closeLix({ lix });
    throw error;
  }
}

async function persistSharedSession(session: SharedSession): Promise<void> {
  if (!session.durable) return;
  const saving = session.saving
    .catch(() => undefined)
    .then(async () => {
      const draft = await loadFolioContentSnapshotFromIdb(session.folioId);
      const blocks = await getDraftBlocks(session.folioId, session.lix);
      const source = await kvGet(session.lix, sourceKey(session.folioId));
      if (
        draft &&
        draft.html === blocks.map((block) => block.html).join("") &&
        (draft.typstSource ?? null) === source
      ) {
        session.checkpointDraft = {
          html: draft.html,
          typstSource: draft.typstSource,
        };
      }
      const blob = await toBlob({ lix: session.lix });
      await saveSharedLixSnapshotToIdb(session.lixId, {
        folioId: session.folioId,
        blob,
        draft: session.checkpointDraft,
      });
    });
  session.saving = saving;
  await saving;
}

export async function persistSharedLix(): Promise<void> {
  if (_shared) await persistSharedSession(_shared);
}

export async function sharedLixBlob(): Promise<Blob> {
  if (!_shared) throw new Error("No shared document is open.");
  return toBlob({ lix: _shared.lix });
}

/** Point the shared document at the relay and let the SDK start syncing. */
  draftHtml: string,
  options: { isCurrent?: () => boolean } = {},
): Promise<{ lixId: string } | null> {
  const isCurrent = options.isCurrent ?? (() => true);
  const serverUrl = lixServerUrl();
  const draftLixId = await openShareableLix(folioId, isCurrent);
  if (!draftLixId) return null;
  let result: { lixId: string; alreadyShared: boolean };
  try {
    await syncDraftToLix(folioId, draftHtml);
    const blob = await sharedLixBlob();
    if (!isCurrent()) {
      await closeSharedLix(draftLixId);
      return null;
    }
    result = await client.action(api.collaboration.shareFolio, {
      folioId,
      folioName,
      lixId: draftLixId,
      blob: await blob.arrayBuffer(),
    });
    if (!isCurrent()) {
      await closeSharedLix(draftLixId);
      return null;
    }
    if (!result.alreadyShared) await enableSharedSync(serverUrl);
  } catch (error) {
    await closeSharedLix(draftLixId);
    throw error;
  }
  if (result.alreadyShared) {
    // Another tab shared this folio first. Open that document instead of
    // the copy just built, which the server discarded.
    await closeSharedLix(draftLixId);
    if (!(await joinSharedLix(client, result.lixId, { isCurrent })))
      return null;
    return { lixId: result.lixId };
  }
  _currentLixId = draftLixId;
  return { lixId: draftLixId };
}

/**
 * Open a shared document: fetch its blob from the relay, open it as the
 * shared session for its folio, and start syncing. Owners reopening their
 * own share use this too, so their edits keep flowing after a reload.
 */
export async function joinSharedLix(
  client: ConvexClient,
  lixId: string,
  options: { isCurrent?: () => boolean } = {},
): Promise<{
  folioId: string;
  role: "owner" | "editor" | "commenter";
  html: string;
} | null> {
  const generation = ++_joinGeneration;
  const isCurrent = () =>
    generation === _joinGeneration && options.isCurrent?.() !== false;
  const meta = await client.query(api.collaboration.getSharedLixMeta, {
    lixId,
  });
  if (!isCurrent()) return null;
  if (!meta) throw new Error("Not a collaborator on this document.");
  if (sharedSessionLixId() === lixId) {
    const blocks = await getDraftBlocks(meta.folioId);
    return isCurrent()
      ? {
          folioId: meta.folioId,
          role: meta.role,
          html: blocks.map((b) => b.html).join(""),
        }
      : null;
  }

  const serverUrl = lixServerUrl();
  // Authenticate and recheck membership before opening a device-local cache.
  // Its vector clock lets the SDK merge unsent changes, instead of replacing
  // a newer local manuscript with the last server snapshot on every reload.
  let lix = await openCachedSharedLix(lixId, meta.folioId);
  if (!lix) {
    if (!isCurrent()) return null;
    const resp = await fetch(`${serverUrl}/lsp/get-v1`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ lix_id: lixId }),
    });
    if (!isCurrent()) return null;
    if (!resp.ok) {
      throw new Error(`Failed to fetch shared Lix (${resp.status})`);
    }
    lix = await openLixInMemory({
      blob: await resp.blob(),
      keyValues: [{ key: "lix_sync", value: "false" }],
      providePlugins: [
        (await import("@lix-js/plugin-json")).plugin as unknown as any,
      ],
    });
  }
  try {
    if (!isCurrent()) {
      await closeLix({ lix });
      return null;
    }
    const blocks = await getDraftBlocks(meta.folioId, lix);
    await enableSharedSync(serverUrl, lix);
    if (!(await installSharedLix(lixId, meta.folioId, lix, { isCurrent }))) {
      await closeLix({ lix });
      return null;
    }
    _currentLixId = lixId;
    return {
      folioId: meta.folioId,
      role: meta.role,
      html: blocks.map((b) => b.html).join(""),
    };
  } catch (error) {
    await closeLix({ lix });
    throw error;
  }
}

let _joinGeneration = 0;

/** Leave a shared document; its folio falls back to the local store. */
export async function leaveSharedLix(lixId: string): Promise<void> {
  if (sharedSessionLixId() !== lixId) return;
  await closeSharedLix(lixId);
}

