        const share = fixture.shares.find((row) => row.lixId === args.lixId);
        return share ? { ...share, role: "owner" } : null;
      }
      if (["collaboration:getCollaborators", "collaboration:getPresence", "collaboration:listPendingInvitations", "collaboration:listSharedWithMe"].includes(name)) return [];
      return null;
    };
    prototype.action = async (reference: unknown, args: FixtureShare) => {
      if (getFunctionName(reference) !== "collaboration:shareFolio") return null;
      fixture.shares.push({ lixId: args.lixId, folioId: args.folioId, folioName: args.folioName });
      localStorage.setItem("sharing-browser-fixture", JSON.stringify(fixture.shares));
      return { lixId: args.lixId, alreadyShared: false };
    };
    prototype.mutation = async (reference: unknown, args: { lixId: string }) => {
      if (getFunctionName(reference) === "collaboration:unshareFolio") {
        fixture.shares = fixture.shares.filter((row) => row.lixId !== args.lixId);
        localStorage.setItem("sharing-browser-fixture", JSON.stringify(fixture.shares));
      }
      return { ok: true };
    };
    const originalFetch = window.fetch.bind(window);
    window.fetch = (input, init) => {
      const url = input instanceof Request ? input.url : String(input);
      if (url.includes("/lsp/")) return Promise.resolve(new Response("Offline sharing fixture", { status: 503 }));
      return originalFetch(input, init);
    };
    const authPath = "/src/utils/auth-client.ts";
    const { authClient } = await import(/* @vite-ignore */ authPath);
    authClient.useSession.set({
      ...authClient.useSession.get(),
      isPending: false,
      data: { user: { id: "sharing-browser-user", email: "sharing@example.test", name: "Sharing fixture" }, session: { id: "sharing-browser-session" } },
    });
  });
  await expect(page.getByTitle("Share this folio with collaborators")).toBeVisible();
}

async function openEditor(page: Page) {
  page.on("dialog", (dialog) => dialog.accept());
  await page.route(/\/api\/auth\//, (route) => route.fulfill({
    contentType: "application/json",
    headers: { "access-control-allow-origin": route.request().headers().origin ?? "*", "access-control-allow-credentials": "true" },
    body: "null",
  }));
  await page.route("**/__sharing_seed", (route) => route.fulfill({ contentType: "text/html", body: "<!doctype html><title>Sharing fixture</title>" }));
  await page.goto("/__sharing_seed");
  await page.evaluate(async () => {
    const path = "/src/utils/idb.ts";
    const db = await import(/* @vite-ignore */ path);
    const now = Date.now();
    await db.saveFoliosToIdb(["a", "b"].map((id) => ({ id: `sharing-${id}`, name: `Sharing regression ${id.toUpperCase()}`, type: "draft", createdAt: now, updatedAt: now })));
    await db.saveFolioContentToIdb("sharing-a", "<p>Original manuscript before sharing.</p>");
    await db.saveFolioContentToIdb("sharing-b", "<p>Second private manuscript.</p>");
    await db.saveActiveFolioIdToIdb("sharing-a");
    await db.saveMetaToIdb("live-review-enabled", false);
    await db.saveMetaToIdb("signin-toast-dismissed", true);
    localStorage.setItem("living-desk-open", "false");
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  });
  await page.goto("/editor/");
  await expect(manuscript(page)).toContainText("Original manuscript", { timeout: 60_000 });
  await installSharingFixture(page);
}

async function share(page: Page) {
  await page.getByTitle("Share this folio with collaborators").click();
  await page.getByRole("button", { name: "Share this folio", exact: true }).click();
  await expect(page.getByRole("button", { name: "Stop sharing", exact: true })).toBeVisible();
  await page.getByRole("button", { name: "✕", exact: true }).click();
}

async function diskHtml(page: Page) {
  return page.evaluate(async () => {
    const path = "/src/utils/idb.ts";
    return (await import(/* @vite-ignore */ path)).loadFolioContentFromIdb("sharing-a");
  });
}

for (const width of [1280, 390]) {
