      _lixPromise = null; // allow retry on next call
    }
  });

  return opening;
}

/* ── Shared session: one folio's draft, synced through the relay ──
 *
 * A shared document is its own Lix holding a single folio's manuscript. It
 * lives beside the local store, never in place of it: the local store carries
 * every folio, the bibliography and pending suggestions, so swapping it in
 * would push all of that to collaborators, and persisting the shared copy
 * would overwrite a collaborator's own work. Draft reads and writes for the
 * shared folio route here; everything else stays local and unsynced.
 */

interface SharedSession {
  lixId: string;
  folioId: string;
  lix: LixInstance;
  durable: boolean;
  saving: Promise<void>;
  checkpointDraft: SharedLixSnapshot["draft"];
}

let _shared: SharedSession | null = null;

async function lixFor(folioId: string): Promise<LixInstance> {
  return _shared?.folioId === folioId ? _shared.lix : getLix();
}

function forgetMirror(folioId: string) {
  mirroredBlocks.delete(folioId);
  mirroredSources.delete(folioId);
  mirroredOrder.delete(folioId);
}

export function sharedSessionLixId(): string | null {
  return _shared?.lixId ?? null;
}

/** Open an empty Lix that will hold only `folioId`'s manuscript. */
export async function openShareableLix(
  folioId: string,
  isCurrent: () => boolean = () => true,
): Promise<string | null> {
  const lix = await openLixInMemory({
    providePlugins: [jsonPlugin as unknown as any],
    keyValues: [{ key: "lix_sync", value: "false" }],
  });
  const row = await lix.db
    .selectFrom("key_value")
    .where("key", "=", "lix_id")
    .select("value")
    .executeTakeFirstOrThrow();
  if (
    !(await installSharedLix(row.value, folioId, lix, {
      durable: false,
      isCurrent,
    }))
  ) {
    await closeLix({ lix });
    return null;
  }
  return row.value;
}

/** Make `lix` the shared document for `folioId`, closing any previous one. */
export async function installSharedLix(
  lixId: string,
  folioId: string,
  lix: LixInstance,
  options: { isCurrent?: () => boolean; durable?: boolean } = {},
): Promise<boolean> {
  if (options.isCurrent?.() === false) return false;
  const next: SharedSession = {
    lixId,
    folioId,
    lix,
    durable: options.durable ?? true,
    saving: Promise.resolve(),
    checkpointDraft: await loadFolioContentSnapshotFromIdb(folioId),
  };
  await persistSharedSession(next);
  if (options.isCurrent?.() === false) return false;
  await closeSharedLix();
  if (options.isCurrent?.() === false) return false;
  _shared = next;
  forgetMirror(folioId);
  startAutosave();
  return true;
}

/** Restore the document's vector clock and unsent changes before pulling. */
export async function openCachedSharedLix(
  lixId: string,
  folioId: string,
): Promise<LixInstance | null> {
  const cached = await loadSharedLixSnapshotFromIdb(lixId);
  if (!cached || cached.folioId !== folioId) return null;
  const lix = await openLixInMemory({
    blob: cached.blob,
    providePlugins: [jsonPlugin as unknown as any],
    keyValues: [{ key: "lix_sync", value: "false" }],
  });
  try {
    const draft = await loadFolioContentSnapshotFromIdb(folioId);
    // The editor can commit to IndexedDB before its Lix debounce runs. Only
    // replay content changed since this checkpoint; an older unchanged local
    // snapshot must not roll back remote changes already in the cached Lix.
    if (
      draft &&
      (draft.html !== cached.draft?.html ||
        draft.typstSource !== cached.draft?.typstSource)
    ) {
      const blocks = splitBlocks(draft.html);
      await lix.db.transaction().execute(async (db) => {
        await db
          .deleteFrom("key_value")
          .where("key", "like", `tw:draft:${folioId}:%`)
          .execute();
        await db
          .insertInto("key_value")
          .values([
            ...blocks.map((block) => ({
              key: blockKey(folioId, block.id),
              value: block.html,
            })),
            {
              key: orderKey(folioId),
              value: JSON.stringify(blocks.map((block) => block.id)),
            },
            ...(draft.typstSource !== undefined
              ? [{ key: sourceKey(folioId), value: draft.typstSource }]
              : []),
          ])
          .execute();
      });
    }
    return lix;
  } catch (error) {
    await closeLix({ lix });
    throw error;
  }
}

async function persistSharedSession(session: SharedSession): Promise<void> {
  if (!session.durable) return;
  const saving = session.saving
    .catch(() => undefined)
    .then(async () => {
      const draft = await loadFolioContentSnapshotFromIdb(session.folioId);
      const blocks = await getDraftBlocks(session.folioId, session.lix);
      const source = await kvGet(session.lix, sourceKey(session.folioId));
      if (
        draft &&
        draft.html === blocks.map((block) => block.html).join("") &&
        (draft.typstSource ?? null) === source
      ) {
        session.checkpointDraft = {
          html: draft.html,
          typstSource: draft.typstSource,
        };
      }
      const blob = await toBlob({ lix: session.lix });
      await saveSharedLixSnapshotToIdb(session.lixId, {
        folioId: session.folioId,
        blob,
        draft: session.checkpointDraft,
      });
    });
  session.saving = saving;
  await saving;
}

export async function persistSharedLix(): Promise<void> {
  if (_shared) await persistSharedSession(_shared);
}

export async function sharedLixBlob(): Promise<Blob> {
  if (!_shared) throw new Error("No shared document is open.");
  return toBlob({ lix: _shared.lix });
}

/** Point the shared document at the relay and let the SDK start syncing. */
export async function enableSharedSync(
  serverUrl: string,
  lix: LixInstance | null = _shared?.lix ?? null,
): Promise<void> {
  if (!lix) throw new Error("No shared document is open.");
  for (const [key, value] of [
    ["lix_server_url", serverUrl],
    ["lix_sync", "true"],
  ]) {
    await kvUpsert(lix, key, value);
  }
  if (_shared?.lix === lix) {
    _shared.durable = true;
    await persistSharedSession(_shared);
  }
}

/**
 * Close the shared document. Closing its database stops the sync loop. With
 * `lixId`, only that document is closed, so a late close cannot tear down a
 * session opened for the next folio.
 */
export async function closeSharedLix(lixId?: string): Promise<void> {
  const previous = _shared;
  if (!previous || (lixId && previous.lixId !== lixId)) return;
  _shared = null;
  forgetMirror(previous.folioId);
  try {
    await persistSharedSession(previous);
  } finally {
    await closeLix({ lix: previous.lix });
  }
}

function markDirty() {
  _dirty = true;
}

function startAutosave() {
  if (_autosaveTimer) return;
  _autosaveTimer = setInterval(async () => {
    if (!_dirty || (!_lix && !_shared)) return;
    _dirty = false;
    await persistToIdb();
  }, AUTOSAVE_INTERVAL_MS);

  if (typeof window !== "undefined") {
    window.addEventListener("beforeunload", () => {
      if (_dirty && (_lix || _shared)) {
        _dirty = false;
        void persistToIdb();
      }
    });
  }
}

export async function persistToIdb() {
  await persistSharedLix();
  if (_lix) {
    const blob = await toBlob({ lix: _lix });
    await saveLixBlobToIdb(blob);
  }
}

export async function readFileAsJson<T>(path: string): Promise<T | null> {
  const lix = await getLix();
  const row = await lix.db
    .selectFrom("file")
    .where("path", "=", path)
    .select("data")
    .executeTakeFirst();
  if (!row) return null;
  const parsed = JSON.parse(new TextDecoder().decode(row.data));
  return parsed as T | null;
}
}

/**
 * Promote a local folio to a shared, server-hosted Lix instance containing
 * only that folio's manuscript. Returns the new document's lixId.
 */
export async function promoteToShared(
  client: ConvexClient,
  folioId: string,
  folioName: string,
  draftHtml: string,
  options: { isCurrent?: () => boolean } = {},
): Promise<{ lixId: string } | null> {
  const isCurrent = options.isCurrent ?? (() => true);
  const serverUrl = lixServerUrl();
  const draftLixId = await openShareableLix(folioId, isCurrent);
  if (!draftLixId) return null;
  let result: { lixId: string; alreadyShared: boolean };
  try {
    await syncDraftToLix(folioId, draftHtml);
    const blob = await sharedLixBlob();
    if (!isCurrent()) {
      await closeSharedLix(draftLixId);
      return null;
    }
    result = await client.action(api.collaboration.shareFolio, {
      folioId,
      folioName,
      lixId: draftLixId,
      blob: await blob.arrayBuffer(),
    });
    if (!isCurrent()) {
      await closeSharedLix(draftLixId);
      return null;
    }
    if (!result.alreadyShared) await enableSharedSync(serverUrl);
  } catch (error) {
    await closeSharedLix(draftLixId);
    throw error;
  }
  if (result.alreadyShared) {
    // Another tab shared this folio first. Open that document instead of
    // the copy just built, which the server discarded.
    await closeSharedLix(draftLixId);
    if (!(await joinSharedLix(client, result.lixId, { isCurrent })))
      return null;
    return { lixId: result.lixId };
  }
  _currentLixId = draftLixId;
  return { lixId: draftLixId };
}

/**
 * Open a shared document: fetch its blob from the relay, open it as the
 * shared session for its folio, and start syncing. Owners reopening their
 * own share use this too, so their edits keep flowing after a reload.
 */
export async function joinSharedLix(
  client: ConvexClient,
  lixId: string,
  options: { isCurrent?: () => boolean } = {},
): Promise<{
  folioId: string;
  role: "owner" | "editor" | "commenter";
  html: string;
} | null> {
  const generation = ++_joinGeneration;
  const isCurrent = () =>
    generation === _joinGeneration && options.isCurrent?.() !== false;
  const meta = await client.query(api.collaboration.getSharedLixMeta, {
    lixId,
  });
  if (!isCurrent()) return null;
  if (!meta) throw new Error("Not a collaborator on this document.");
  if (sharedSessionLixId() === lixId) {
    const blocks = await getDraftBlocks(meta.folioId);
    return isCurrent()
      ? {
          folioId: meta.folioId,
          role: meta.role,
          html: blocks.map((b) => b.html).join(""),
        }
      : null;
  }

  const serverUrl = lixServerUrl();
  // Authenticate and recheck membership before opening a device-local cache.
  // Its vector clock lets the SDK merge unsent changes, instead of replacing
  // a newer local manuscript with the last server snapshot on every reload.
  let lix = await openCachedSharedLix(lixId, meta.folioId);
  if (!lix) {
    if (!isCurrent()) return null;
    const resp = await fetch(`${serverUrl}/lsp/get-v1`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ lix_id: lixId }),
    });
    if (!isCurrent()) return null;
    if (!resp.ok) {
      throw new Error(`Failed to fetch shared Lix (${resp.status})`);
    }
    lix = await openLixInMemory({
      blob: await resp.blob(),
      keyValues: [{ key: "lix_sync", value: "false" }],
      providePlugins: [
        (await import("@lix-js/plugin-json")).plugin as unknown as any,
      ],
    });
  }
  try {
    if (!isCurrent()) {
      await closeLix({ lix });
      return null;
    }
    const blocks = await getDraftBlocks(meta.folioId, lix);
    await enableSharedSync(serverUrl, lix);
    if (!(await installSharedLix(lixId, meta.folioId, lix, { isCurrent }))) {
      await closeLix({ lix });
      return null;
    }
    _currentLixId = lixId;
    return {
      folioId: meta.folioId,
      role: meta.role,
      html: blocks.map((b) => b.html).join(""),
    };
  } catch (error) {
    await closeLix({ lix });
    throw error;
  }
}

let _joinGeneration = 0;

/** Leave a shared document; its folio falls back to the local store. */
export async function leaveSharedLix(lixId: string): Promise<void> {
  if (sharedSessionLixId() !== lixId) return;
  await closeSharedLix(lixId);
}

/* ── Remote → local sync ────────────────────────────────────────── */

import type { Editor } from "@tiptap/core";
import { getDraftBlocks, getDraftTypstSource } from "./lix";
import { saveFolioTypstToIdb } from "./idb";
import { reconcileTypstSource } from "./typst/document";

let _remoteSyncTimer: ReturnType<typeof setInterval> | null = null;
let _lastPolledHtml: string | null = null;
let _lastPolledSource: string | null = null;
let _remoteSyncGeneration = 0;

/**
 * Poll the local Lix instance for remote changes and reflect them into the
 * Tiptap editor. `initSyncProcess` (from the Lix SDK) pulls remote change-sets
 * into the in-memory Lix in the background; this function reads the resulting
 * draft blocks every ~1.5 s and, when they differ from the last poll, updates
 * the editor content with `emitUpdate: false` so the change doesn't re-trigger
 * `syncDraftToLix`.
 *
 * Race-free by design:
 *   • When the local editor types, `syncDraftToLix` mirrors HTML→Lix (debounced).
 *     The next poll sees the same content, updates `_lastPolledHtml` to match,
 *     and skips the editor update — the editor already has this content.
 *   • Only a *remote* change (arrived via pull→merge) will make the polled HTML
 *     differ from `_lastPolledHtml`, triggering an editor update.
 */
export function watchRemoteChanges(editor: Editor, folioId: string): void {
  stopWatchingRemote();
  const generation = _remoteSyncGeneration;
  const isCurrent = () =>
    generation === _remoteSyncGeneration && !editor.isDestroyed;

  const poll = async () => {
    try {
      const blocks = await getDraftBlocks(folioId);
      const rawSource = await getDraftTypstSource(folioId);
      if (!isCurrent()) return;
      if (blocks.length === 0 && rawSource === null) return;
      const html = blocks.map((b) => b.html).join("");
      const source =
        rawSource === null ? null : reconcileTypstSource(rawSource, html);
      if (html === _lastPolledHtml && source === _lastPolledSource) return;
      _lastPolledHtml = html;
      _lastPolledSource = source;
      if (source !== null) {
        // This is a collaborator's snapshot, never an acknowledgement of
        // the writer's pending visual save or source draft.
        await saveFolioTypstToIdb(folioId, source, html, undefined, "remote");
        await persistSharedLix();
        if (!isCurrent()) return;
        window.dispatchEvent(
          new CustomEvent("twyne:typst-remote-change", {
            detail: { folioId, source, html },
          }),
        );
      }
      // Only update if the editor doesn't already have this content (avoids
      // clobbering cursor position when the change was local & already mirrored).
      const sourceDraft: { folioId: string; pending?: boolean } = { folioId };
      window.dispatchEvent(
        new CustomEvent("twyne:request-typst-source", { detail: sourceDraft }),
      );
      if (!sourceDraft.pending && editor.getHTML() !== html) {
        window.dispatchEvent(
          new CustomEvent("twyne:typst-applying", { detail: { folioId } }),
        );
        editor.commands.setContent(html, { emitUpdate: false });
      }
    } catch {
      // Lix not ready or transient — best-effort.
    }
  };

  void poll();
  _remoteSyncTimer = setInterval(poll, 1500);
}

export function stopWatchingRemote(): void {
  _remoteSyncGeneration += 1;
  if (_remoteSyncTimer) {
    clearInterval(_remoteSyncTimer);
    _remoteSyncTimer = null;
  }
  _lastPolledHtml = null;
  _lastPolledSource = null;
}

