import {
  component$,
  useStore,
  useSignal,
  useVisibleTask$,
  $,
  type PropFunction,
} from "@qwik.dev/core";
import { useConvexClient } from "../../utils/convex-context";
import { accountDisplayName } from "../../utils/account-display";
import {
  hasAuthenticatedConvexIdentity,
  useAuth,
} from "../../utils/auth-context";
import { api } from "../../../convex/_generated/api";
import {
  promoteToShared,
