interface ShareState {
  open: boolean;
  shared: boolean;
  lixId: string | null;
  folioId: string;
  folioName: string;
  sharing: boolean;
  error: AppError | null;
  inviteEmail: string;
  inviteRole: "editor" | "commenter";
  inviting: boolean;
  inviteMsg: string | null;
  inviteError: AppError | null;
  collaborators: Array<{
    userId: string;
    role: string;
    status: string;
    invitedAt: number;
    acceptedAt?: number;
  }>;
  confirmingUnshare: boolean;
}

interface PresenceUser {
  userId: string;
  displayName: string;
  color: string;
  cursorPos?: number;
}

export const ShareDialog = component$(
  (props: {
    folioId: string;
