          folioId,
          folioName,
          draftHtml,
          { isCurrent },
        );
        if (!result || !isCurrent()) return;
        const { lixId } = result;
        const opened = await props.onShared$?.(lixId, folioId, draftHtml);
        if (!isCurrent() || opened === false) return;
        store.lixId = lixId;
        store.shared = true;
      } catch (error) {
        reportApplicationDiagnostic("twyne:collaboration:share", error, {
          operation: "share-folio",
        });
        store.error = normalizeApplicationError(error, {
          source: "convex",
          metadata: { operation: "share-folio" },
        });
      } finally {
        store.sharing = false;
