                ? {
                    backgroundColor: "var(--color-vermilion)",
                    borderColor: "var(--color-vermilion)",
                    fontFamily: "var(--font-typewriter)",
                  }
                : undefined
            }
          >
            {props.confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
});

