        "<p>New remote manuscript</p>",
      );
    } finally {
      await closeLix({ lix: cached! });
    }
  });

  test("a cancelled fetch cannot replace the next folio's shared session", async () => {
    let current = true;
    let respond!: (response: Response) => void;
    vi.mocked(fetch).mockImplementation(
      () =>
        new Promise((resolve) => {
